/**
 * National Issue Templates Seed Data
 *
 * 120+ templates across 7 domains for the National Issues Engine.
 * Each template uses {{variable}} substitution and JSON trigger conditions.
 *
 * Run: npx ts-node prisma/seeds/national-issue-templates.ts
 */

export interface IssueTemplateSeed {
  slug: string;
  title: string;
  description: string;
  longDescription?: string;
  domain: string;
  category: string;
  baseSeverity: string;
  baseUrgency: number;
  deadlineDaysBase: number | null;
  triggerConditions: string;
  cooldownDays: number;
  maxActivePerCountry: number;
  responseOptions: string;
  followUpTemplateIds?: string;
  personalityModifiers?: string;
  tags?: string;
}

// Helper to build trigger JSON
function trigger(cond: object): string {
  return JSON.stringify(cond);
}

function options(opts: object[]): string {
  return JSON.stringify(opts);
}

